use std::rc::Rc;use std::cell::RefCell;impl Solution{pub fn flatten(root:&mut Option<Rc<RefCell<TreeNode>>>){fn preorder(n:&Option<Rc<RefCell<TreeNode>>>,v:&mut Vec<Rc<RefCell<TreeNode>>>){if let Some(x)=n{v.push(x.clone());let b=x.borrow();preorder(&b.left,v);preorder(&b.right,v);}}let mut v=vec![];preorder(root,&mut v);for i in 0..v.len(){let mut b=v[i].borrow_mut();b.left=None;b.right=if i+1<v.len(){Some(v[i+1].clone())}else{None};}}}
